def valid_palindrome(s: str) -> bool:
    """Return True if s is a palindrome ignoring non-alphanumeric characters and case.

    If s is None, treat it as a palindrome (consistent with previous behavior).
    """
    if s is None:
        return True
    i, j = 0, len(s) - 1
    while i < j:
        # move i forward to next alphanumeric
        while i < j and not s[i].isalnum():
            i += 1
        # move j backward to previous alphanumeric
        while i < j and not s[j].isalnum():
            j -= 1
        if i < j:
            if s[i].lower() != s[j].lower():
                return False
            i += 1
            j -= 1
    return True

def fibonacci(n: int) -> int:
    """Return the nth Fibonacci number with fib(0)=0 and fib(1)=1.

    Args:
        n: A non-negative integer index.

    Returns:
        The nth Fibonacci number as an int.

    Raises:
        TypeError: if n is not an int or is a bool.
        ValueError: if n is negative.
    """
    # Reject booleans explicitly (they are instances of int in Python)
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")

    # Fast doubling method: returns (F(n), F(n+1))
    def _fib_pair(k: int) -> tuple[int, int]:
        if k == 0:
            return (0, 1)
        a, b = _fib_pair(k >> 1)
        c = a * ((b << 1) - a)  # F(2m) = F(m) * (2*F(m+1) − F(m))
        d = a * a + b * b      # F(2m+1) = F(m)^2 + F(m+1)^2
        if k & 1:
            return (d, c + d)
        else:
            return (c, d)

    return _fib_pair(n)[0]

def climbing_stairs(n: int) -> int:
    """Return the number of distinct ways to climb n steps taking 1 or 2 steps.

    Behavior:
    - If n < 0: return 0
    - If n == 0: return 1
    - For n >= 1: compute ways using recurrence ways(n)=ways(n-1)+ways(n-2).

    Raises TypeError if n is not an int.
    """
    if not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n == 1:
        return 1
    a, b = 1, 1  # ways(0)=1, ways(1)=1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def two_sum(nums: list[int], target: int) -> list[int]:
    num_map = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_map:
            return [num_map[complement], i]
        num_map[num] = i
    return []

